def parse_nested_parens(paren_string: str) -> List[int]:
    levels = []

    for group in paren_string.split():
        level = 0

        for char in group:
            if char == '(':
                level += 1
            elif char == ')':
                level -= 1

            # Ensure we don't go below zero (i.e., no unbalanced parentheses)
            level = max(level, 0)

        levels.append(level)

    return levels

