def minPath(grid, k):
    N = len(grid)

    def dfs(i, j, path, visited):
        if len(path) == k:
            return path

        for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
            if 0 <= x < N and 0 <= y < N and grid[x][y] not in visited:
                new_path = path + [grid[x][y]]
                result = dfs(x, y, new_path, visited | {grid[x][y]})

                if result is not None:
                    return result

        return None

    min_val = float('inf')

    for i in range(N):
        for j in range(N):
            path = [grid[i][j]]

            res = dfs(i, j, path, {grid[i][j]})

            if res is not None:
                val = ''.join(map(str, sorted(res)))

                min_val = min(min_val, int(val))

    return list(int(d) for d in str(min_val))

