               for j in range(i + 1, n) 
               if ((i * i - i + 1) + (j * j - j + 1)) % 3 == 0)

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    idx1 = planets.index(planet1)
    idx2 = planets.index(planet2)

    start_idx = min(idx1, idx2) + 1
    end_idx = max(idx1, idx2)

    result = tuple([planets[i] for i in range(start_idx, end_idx)])

    return result

def x_or_y(n, x, y):
    if n > 1: 
        is_prime = True
        for i in range(2, int(n**0.5) + 1): 
            if (n % i) == 0:
                is_prime = False
                break
        return x if is_prime else y

def find_max(words):
    max_word = ""
    max_chars = 0
    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_chars or (unique_chars == max_chars and word < max_word):
            max_word = word
            max_chars = unique_chars
    return max_word

def do_algebra(operator, operand):
    result = 0
    for i in range(len(operand) - 1):
        if operator[i] == '+':
            result += operand[i]
        elif operator[i] == '-':
            result -= operand[i]
        elif operator[i] == '*':
            result *= operand[i]
        elif operator[i] == '//':
            result //= operand[i]
        else:
            result **= operand[i]
    return result

def solve(s):
    result = ""
    for char in s:
        if 'a' <= char.lower() <= 'z':
            result += char.swapcase()
        elif 'A' <= char <= 'Z':
            result += char.swapcase()
        else:
            result += char
    return result[::-1]

import hashlib

def string_to_md5(text):
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()
